package br.com.sussmartcare.triage.infrastructure.messaging; import br.com.sussmartcare.triage.application.TriageApplicationService; import br.com.sussmartcare.triage.infrastructure.projection.*; import com.fasterxml.jackson.databind.*; import java.util.*; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; @Component public class CheckInConsumer{private final ObjectMapper mapper;private final ProcessedEventRepository processed;private final TriageApplicationService app;public CheckInConsumer(ObjectMapper m,ProcessedEventRepository p,TriageApplicationService a){mapper=m;processed=p;app=a;}@KafkaListener(topics="patient-checked-in",groupId="triage-checkin")@Transactional public void consume(String raw)throws Exception{var e=mapper.readTree(raw);UUID eventId=UUID.fromString(e.path("eventId").asText());if(processed.existsById(eventId))return;UUID visit=UUID.fromString(e.path("data").path("visitId").asText());app.startIfAbsent(visit);processed.save(new ProcessedEvent(eventId,"triage-checkin"));}}
